import { test, expect } from '@playwright/test';

test.describe('Search Input Focus on / Key Press', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should focus search input when / is pressed', async ({ page }) => {
    // Verify search input is visible and not focused
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).not.toBeFocused();

    // Press / key
    await page.keyboard.press('\\');

    // Verify search input is now focused
    await expect(searchInput).toBeFocused();

    // Verify search input has placeholder text
    await expect(searchInput).toHaveValue('');

    // Verify search button is visible and enabled
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();
    await expect(searchButton).toBeEnabled();

    // Verify search results container is visible
    const searchResults = page.locator('[data-testid="search-results"]');
    await expect(searchResults).toBeVisible();
  });

  test('should not focus search input when / is pressed outside of input', async ({ page }) => {
    // Verify search input is visible and not focused
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).not.toBeFocused();

    // Press / key
    await page.keyboard.press('\\');

    // Verify search input is still not focused
    await expect(searchInput).not.toBeFocused();

    // Verify search button is still visible and enabled
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();
    await expect(searchButton).toBeEnabled();

    // Verify search results container is still visible
    const searchResults = page.locator('[data-testid="search-results"]');
    await expect(searchResults).toBeVisible();

    // Verify search input placeholder text is still present
    await expect(searchInput).toHaveValue('');
  });
});
